cd ~/Projects/project; node -e '
const j=require("./evidence/bench.docker9.json");const md=require("fs").readFileSync("evidence/bench.docker9.md","utf8");
const sc={};for(const l of md.split("\n")){const m=l.match(/^\| (\S+) \| \*\*([\d.]+)\*\*/);if(m)sc[m[1]]=+m[2]}
const k=(b,s,f)=>j.results[b][s].kpi[f].mean;
console.log(Object.keys(j.results.bun));
let rows=Object.keys(j.results).map(b=>{const r=j.results[b];return {b,s:sc[b],rd:k(b,"read","rps"),li:k(b,"list","rps"),wr:k(b,"write","rps"),mx:k(b,"mixed","rps"),ct:r.contention?Object.values(r.contention.kpi).map(x=>x.mean):null,rp:k(b,"read","p99"),wp:k(b,"write","p99")}});
console.log(JSON.stringify(j.results.bun.contention.kpi).slice(0,400));
' ; docker compose -f bench/docker-compose.yml down 2>&1 | tail -2; date

