input.command:
cd ~/Projects/project; node -e '
const j=require("./evidence/bench.docker9.json");const md=require("fs").readFileSync("evidence/bench.docker9.md","utf8");
const sc={};for(const l of md.split("\n")){const m=l.match(/^\| (\S+) \| \*\*([\d.]+)\*\*/);if(m)sc[m[1]]=+m[2]}
const k=(b,s,f)=>j.results[b][s].kpi[f].mean;
const rows=Object.keys(j.results).map(b=>[b,sc[b],k(b,"read","rps"),k(b,"list","rps"),k(b,"write","rps"),k(b,"mixed","rps"),k(b,"contention","successWritesPerSec"),k(b,"read","p99"),k(b,"write","p99")]).sort((a,b)=>b[1]-a[1]);
let o="| backend | score | read req/s | list req/s | write req/s | mixed req/s | contention ok-writes/s | read p99 ms | write p99 ms |\n|---|---|---|---|---|---|---|---|---|\n";
for(const r of rows)o+=`| ${r[0]} | ${r[1]} | ${r.slice(2,7).map(x=>Math.round(x)).join(" | ")} | ${r[7].toFixed(2)} | ${r[8].toFixed(2)} |\n`;
require("fs").writeFileSync("evidence/bench.docker9.raw.md",o);console.log(o)'

